begin;
do $$
declare a uuid:=gen_random_uuid();u uuid:=gen_random_uuid();sport uuid;tid uuid;tpl uuid;rules jsonb;schema jsonb;mid uuid;first_count integer;names text[];before_count integer;
begin
 if to_regclass('auth.users') is not null then
  insert into auth.users(id,email,email_confirmed_at,aud,role) values(a,a||'@knockout-qa.invalid',now(),'authenticated','authenticated'),(u,u||'@knockout-qa.invalid',now(),'authenticated','authenticated');
  insert into public.profiles(id,username) values(a,'koqa-'||substr(a::text,1,20)),(u,'koqa-'||substr(u::text,1,20)) on conflict do nothing;
 end if;
 insert into public.user_roles values(a,'admin'),(u,'user');
 select id into sport from public.sports where slug='darts';
 select jsonb_agg(jsonb_build_object('unit','legs','first_to',ft,'winner_points',1,'exact_points',3) order by ord) into rules from unnest(array[6,6,6,6,7,8]) with ordinality x(ft,ord);
 perform set_config('request.jwt.claim.sub',a::text,true);perform set_config('role','authenticated',true);
 tid:=public.create_knockout_tournament('QA ET blank',sport,'players',array_fill(''::text,array[48]),now()+interval '1 day',rules);
 schema:=public.get_knockout_schema(tid);
 if jsonb_array_length(schema->'roster')<>48 or schema->>'status'<>'draft' then raise exception 'FAIL empty draft';end if;
 if (select count(*) from jsonb_array_elements(schema->'matches')x where not (x->>'bye')::boolean)<>47 then raise exception 'FAIL ET match count';end if;
 if (select count(*) from jsonb_array_elements(schema->'matches')x where (x->>'round')::integer=1 and not (x->>'bye')::boolean)<>16 then raise exception 'FAIL ET round one';end if;
 if (select count(*) from jsonb_array_elements(schema->'matches')x where (x->>'round')::integer=2 and (x->>'home_slot') is not null and (x->>'away_slot') is null)<>16 then raise exception 'FAIL each seed must face R1 winner';end if;
 if exists(select 1 from jsonb_array_elements(schema->'matches')x where (x->>'first_to')::int<>case (x->>'round')::int when 6 then 8 when 5 then 7 else 6 end or (x->>'enabled')::boolean) then raise exception 'FAIL format or empty slot open';end if;
 select (x->>'id')::uuid into mid from jsonb_array_elements(schema->'matches')x where (x->>'round')::int=1 and not (x->>'bye')::boolean limit 1;
 perform public.edit_knockout(tid,'schedule',mid,jsonb_build_object('start',now()+interval '1 day','unit','legs','first_to',6));
 begin perform public.edit_knockout(tid,'publish');raise exception 'FAIL blank publish';exception when raise_exception then if sqlerrm='FAIL blank publish' then raise;end if;end;
 begin perform public.admin_publish_tournament(tid);raise exception 'FAIL legacy blank publish';exception when raise_exception then if sqlerrm='FAIL legacy blank publish' then raise;end if;end;
 begin perform public.edit_knockout(tid,'result',mid,'{"home_score":6,"away_score":2}');raise exception 'FAIL blank result';exception when raise_exception then if sqlerrm='FAIL blank result' then raise;end if;end;
 names:=array_fill(''::text,array[48]);names[1]:='QA Seed';
 perform public.edit_knockout(tid,'roster',null,jsonb_build_object('names',names));
 schema:=public.get_knockout_schema(tid);
 if schema->'roster'->>0<>'QA Seed' or schema->'roster'->>1<>'' then raise exception 'FAIL partial save';end if;
 names[2]:=' qa seed ';
 begin perform public.edit_knockout(tid,'roster',null,jsonb_build_object('names',names));raise exception 'FAIL duplicate names';exception when raise_exception then if sqlerrm='FAIL duplicate names' then raise;end if;end;
 perform set_config('role','postgres',true);
 begin update public.matches set predictions_enabled=true where id=mid;raise exception 'FAIL guard blank open';exception when raise_exception then if sqlerrm='FAIL guard blank open' then raise;end if;end;
 select count(*) into before_count from public.tournaments;
 perform set_config('role','authenticated',true);
 tpl:=public.save_knockout_template('QA ET format',sport,'players',48,rules,'replacement');
 if not exists(select 1 from jsonb_array_elements(public.knockout_catalog()->'templates')x where x->>'id'=tpl::text and (x->>'participant_count')::integer=48 and x->'rules'=rules) then raise exception 'FAIL saved template catalog';end if;
 perform set_config('role','postgres',true);
 if (select count(*) from public.tournaments)<>before_count then raise exception 'FAIL template left temporary tournament';end if;
 perform set_config('role','authenticated',true);perform set_config('request.jwt.claim.sub',u::text,true);
 begin perform public.save_knockout_template('forbidden',sport,'players',48,rules,'replacement');raise exception 'FAIL nonadmin template';exception when insufficient_privilege then null;end;
 begin perform public.knockout_catalog();raise exception 'FAIL nonadmin catalog';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claim.sub',a::text,true);
 names:=array(select 'QA player '||x from generate_series(1,48)x);
 perform public.edit_knockout(tid,'roster',null,jsonb_build_object('names',names));
 perform public.edit_knockout(tid,'publish');
 perform set_config('role','postgres',true);
 if not (select predictions_enabled from public.matches where id=mid) then raise exception 'FAIL filled future match open';end if;
end $$;
rollback;
